    assert requests[0].url.path == "/v1/sandboxes/sbx-1/credential-vault"
    assert json.loads(requests[0].content)["expectedRevision"] == 6
    assert requests[1].url.path == "/v1/sandboxes/sbx-1/credential-vault"

